const items = $input.all();
if (items.length !== 1) throw new Error('Expected one HTTP response');
const r = items[0].json;
if (r.statusCode !== 200) throw new Error('Source HTTP status is not 200');
if (typeof r.body !== 'string' || !r.body.trim() || r.body.length > 200000) throw new Error('Source body missing or unexpectedly large');
if (/<!DOCTYPE|<!ENTITY/i.test(r.body)) throw new Error('DTD/entity declarations are not accepted');
if (!/<nlmSearchResult(?:\s|>)/.test(r.body)) throw new Error('Unexpected source XML root');
return [{json: {data: r.body}}];

const items = $input.all();
if (items.length !== 1) throw new Error('Expected one parsed document');
const root = items[0].json.nlmSearchResult;
if (!root || root.error || !/^\d+$/.test(String(root.count)) || Number(root.count) < 1) throw new Error('Source returned an error or no results');
const value = root.list && root.list.document;
const docs = Array.isArray(value) ? value : value ? [value] : [];
if (docs.length !== 1) throw new Error('Expected one topic from retmax=1');
const doc = docs[0];
const url = doc.$ && doc.$.url;
// Exact HTTPS origin and a topic path; rejects credentials, ports, deceptive hosts and query strings.
if (typeof url !== 'string' || !/^https:\/\/medlineplus\.gov\/[a-z0-9_-]+\.html$/.test(url)) throw new Error('Unexpected source URL');
const fields = Array.isArray(doc.content) ? doc.content : doc.content ? [doc.content] : [];
function field(name) {
  const node = fields.find(n => n.$ && String(n.$.name).toLowerCase() === name.toLowerCase());
  return node && typeof node._ === 'string' ? node._ : '';
}
// Strip markup only to check nonempty text. This is not ingestion or medical validation.
function text(s) { return s.replace(/<[^>]*>/g, ' ').replace(/&(?:#\d+|#x[0-9a-f]+|[a-z]+);/gi, ' ').replace(/\s+/g, ' ').trim(); }
const title = text(field('title'));
const summary = text(field('fullSummary'));
if (!title || !summary) throw new Error('Missing topic title or full summary');
return [{json: {status: 'source_check_passed', checked_at: new Date().toISOString(), source: 'MedlinePlus', query: 'diabetes', http_status: 200, valid_documents: 1, title, source_url: url, summary_characters: summary.length, note: 'Source availability/format check only. No database update, embedding, AI answer or medical validation.'}}];
